p=Path('/opt/molmospaces/assets/scenes/holodeck-objaverse-val/val_1430_ceiling.xml')
root=ET.parse(p).getroot(); base=p.parent/'val_1430_assets'
def rotq(q):
 w,x,y,z=map(float,q.split()) if isinstance(q,str) else q
 return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])
def vec(s,d): return np.array(list(map(float,s.split()))) if s else np.array(d,float)
def verts(obj):
 a=[]
 for line in open(base/(obj+'.obj')):
  if line.startswith('v '): a.append(list(map(float,line.split()[1:4])))
 return np.array(a)
worldbody=root.find('.//worldbody')
for b in worldbody.findall('body'):
 name=b.get('name','')
 if not (name.startswith('wall_') or name.startswith('doorway_') or name.startswith('doorframe_')): continue
